// Des: Tests for st-stat-data: windows, no double send, resume, queue, halt
// Flo: memory db > act on fake clock > assert counts and states
// I/O: rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const data = @import("st-stat-data.zig");
const H: i64 = 3600000; const D: i64 = 86400000; const T = std.testing;
fn opn() !data.Stor { return data.Stor.open(T.allocator, ":memory:"); }
test "first seen is stored once and never moves" { var sto = try opn(); defer sto.close(); try T.expectEqual(@as(i64, 5000), try sto.firstSeen(T.allocator, 5000)); try T.expectEqual(@as(i64, 5000), try sto.firstSeen(T.allocator, 99999)); }
test "windows count only inside hour, minute and day" { var sto = try opn(); defer sto.close(); const now = 3 * D; try sto.actAdd(now - 2 * D, "send"); try sto.actAdd(now - 2 * H, "send"); try sto.actAdd(now - 30 * 60000, "send"); try sto.actAdd(now - 10000, "newc"); try sto.actAdd(now - 5000, "read"); const sta = try sto.statGet(T.allocator, now); try T.expectEqual(@as(u32, 1), sta.minu_cnt); try T.expectEqual(@as(u32, 2), sta.hour_cnt); try T.expectEqual(@as(u32, 3), sta.day_cnt); try T.expectEqual(@as(u32, 1), sta.newc_cnt); try T.expectEqual(@as(i64, now - 10000), sta.last_ms); }
test "window edge is exclusive at exactly one hour" { var sto = try opn(); defer sto.close(); const now = 2 * D; try sto.actAdd(now - H, "send"); try sto.actAdd(now - H + 1, "send"); const sta = try sto.statGet(T.allocator, now); try T.expectEqual(@as(u32, 1), sta.hour_cnt); }
test "send once: fresh, then dup after done" { var sto = try opn(); defer sto.close(); try T.expect(try sto.sendBegin("chat1", "hi", 100) == .fresh); try sto.sendDone("chat1", "hi", 200); try T.expect(try sto.sendBegin("chat1", "hi", 300) == .dup); try T.expect(try sto.sendBegin("chat1", "hi!", 300) == .fresh); try T.expect(try sto.sendBegin("chat2", "hi", 300) == .fresh); const sta = try sto.statGet(T.allocator, 400); try T.expectEqual(@as(u32, 1), sta.day_cnt); }
test "crash after begin: second begin reports pend, never fresh" { var sto = try opn(); defer sto.close(); try T.expect(try sto.sendBegin("c", "msg", 1) == .fresh); try T.expect(try sto.sendBegin("c", "msg", 2) == .pend); try sto.sendDrop("c", "msg"); try T.expect(try sto.sendBegin("c", "msg", 3) == .fresh); }
test "drop never removes a sent row" { var sto = try opn(); defer sto.close(); _ = try sto.sendBegin("c", "m", 1); try sto.sendDone("c", "m", 2); try sto.sendDrop("c", "m"); try T.expect(try sto.sendBegin("c", "m", 3) == .dup); }
test "done without begin is an error" { var sto = try opn(); defer sto.close(); try T.expectError(error.Fail, sto.sendDone("x", "y", 1)); }
test "send key differs by chat and text, not by concatenation" { try T.expect(!std.mem.eql(u8, &data.sendKey("ab", "c"), &data.sendKey("a", "bc"))); try T.expectEqual(@as(usize, 32), data.sendKey("a", "b").len); }
test "messages keep order and tail returns the last N oldest-first" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var cnt: u32 = 0; while (cnt < 5) : (cnt += 1) { var buf: [8]u8 = undefined; try sto.msgAdd("c1", "them", try std.fmt.bufPrint(&buf, "m{d}", .{cnt}), cnt); } try sto.msgAdd("c2", "me", "other", 9); const tail = try sto.msgTail(aren.allocator(), "c1", 3); try T.expectEqual(@as(usize, 3), tail.len); try T.expectEqualStrings("m2", tail[0].body); try T.expectEqualStrings("m4", tail[2].body); const none = try sto.msgTail(aren.allocator(), "zz", 3); try T.expectEqual(@as(usize, 0), none.len); }
test "queue is fifo and survives busy state" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expect((try sto.queNext(aren.allocator())) == null); try sto.queAdd("u1", 1, "reply", "{}"); try sto.queAdd("u2", 2, "remind", "{\"t\":1}"); const one = (try sto.queNext(aren.allocator())).?; try T.expectEqualStrings("reply", one.job); try sto.queSet(one.id, "busy"); const again = (try sto.queNext(aren.allocator())).?; try T.expectEqual(one.id, again.id); try sto.queSet(one.id, "done"); const two = (try sto.queNext(aren.allocator())).?; try T.expectEqualStrings("u2", two.uuid); try T.expectError(error.Fail, sto.queSet(9999, "done")); }
test "log tail is capped and oldest-first" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var cnt: i64 = 0; while (cnt < 4) : (cnt += 1) try sto.logAdd(cnt, "info", "run", "x"); const rows = try sto.logTail(aren.allocator(), 2); try T.expectEqual(@as(usize, 2), rows.len); try T.expectEqual(@as(i64, 2), rows[0].ts); try T.expectEqual(@as(i64, 3), rows[1].ts); }
test "halt set, read, clear" { var sto = try opn(); defer sto.close(); try T.expect((try sto.haltGet(T.allocator)) == null); try sto.haltSet(5, "captcha"); const why = (try sto.haltGet(T.allocator)).?; defer T.allocator.free(why); try T.expectEqualStrings("captcha", why); try sto.haltClear(); try T.expect((try sto.haltGet(T.allocator)) == null); }
test "quotes and unicode survive storage" { var sto = try opn(); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try sto.msgAdd("c", "them", "it's \"ok\" — chào bạn", 1); const tail = try sto.msgTail(aren.allocator(), "c", 1); try T.expectEqualStrings("it's \"ok\" — chào bạn", tail[0].body); }
test "react and upload counters are separate from sends" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); const now = 3 * D; try sto.actAdd(now - 1000, "react"); try sto.actAdd(now - 2000, "react"); try sto.actAdd(now - 3000, "upld"); try sto.actAdd(now - 2 * D, "react"); const sta = try sto.statGet(T.allocator, now); try T.expectEqual(@as(u32, 2), sta.reac_cnt); try T.expectEqual(@as(u32, 1), sta.upld_cnt); try T.expectEqual(@as(u32, 0), sta.day_cnt); }
